def family_init(ctx):
    from collections import deque
    bars = ctx.bars
    N = len(bars)
    h = [float(b["h"]) for b in bars]
    c = [float(b["c"]) for b in bars]
    lb = max(5, int(ctx.p.lb))

    # rolling max of HIGH (the anchor) and of CLOSE (the new-high test), O(N)
    ph = [None] * N
    fresh = [0] * N
    dh = deque()
    dc = deque()
    for j in range(N):
        while dh and h[dh[-1]] <= h[j]:
            dh.pop()
        dh.append(j)
        while dh[0] <= j - lb:
            dh.popleft()
        while dc and c[dc[-1]] <= c[j]:
            dc.pop()
        dc.append(j)
        while dc[0] <= j - lb:
            dc.popleft()
        if j >= lb - 1:
            hi = h[dh[0]]
            if hi > 0.0:
                ph[j] = c[j] / hi
            if c[j] >= c[dc[0]]:
                fresh[j] = 1          # this bar IS a new lb-bar closing high

    # bars since the last fresh high
    excl = max(0, int(ctx.p.excl))
    since = [10 ** 9] * N
    last = -10 ** 9
    for j in range(N):
        if fresh[j]:
            last = j
        since[j] = j - last
    ctx.ph = ctx.series(ph, "ph")
    ctx.fresh = ctx.series(fresh, "fresh_high")
    ctx.since = ctx.series(since, "since_high")


def signal(ctx, i):
    ev = max(1, int(ctx.p.every))
    if i % ev:
        return 0                       # the monthly rebalance clock
    p = ctx.ph[i]
    if p is None:
        return 0
    if float(ctx.p.ph_lo) <= p < 1.0:
        if ctx.fresh[i]:
            return 0                   # never the bar that makes the high
        if ctx.since[i] <= int(ctx.p.excl):
            return 0                   # nor the excl bars after it
        return 1
    if p <= float(ctx.p.ph_short):
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    p = ctx.ph[i]
    if p is None:
        return False
    if ctx.positions[0]["side"] == "long":
        return p < float(ctx.p.ph_exit_long)
    return p > float(ctx.p.ph_exit_short)
